152			chew();
153			skip(1);
154		}
155		if (i == 23) {
156			strcpy(cmdbuf, " ABBREV");
157		}
158		else {
159			strcpy(cmdbuf, "  Mnemonic:  ");
160			j = 0;
161			while ((cmdbuf[j+13] = toupper(commands[i][j])) != 0) j++;
162		}
163		fp = fopen("sst.doc", "r");
164		if (fp == NULL) {
165			prout("Spock-  \"Captain, that information is missing from the");
166			prout("   computer. You need to find SST.DOC and put it in the");
167			prout("   current directory.\"");
168			return;
169		}
170		i = strlen(cmdbuf);
171		do {
172			if (fgets(linebuf, 132, fp) == NULL) {
173				prout("Spock- \"Captain, there is no information on that command.\"");
174				fclose(fp);
175				return;
176			}
177		} while (strncmp(linebuf, cmdbuf, i) != 0);
178	
179		skip(1);
180		prout("Spock- \"Captain, I've found the following information:\"");
181		skip(1);
182	
183		do {
184			if (linebuf[0]!=12) { // ignore page break lines 
185				/* sst.doc has CRLF endings. Dropping only the \n
186				   leaves a \r, and in the full-screen display that
187				   returns the cursor to column 0 so the following
188				   newline wipes the line that was just drawn --
189				   which is why help used to come out blank there. */
190				char *end = linebuf + strlen(linebuf);
191				while (end > linebuf && (end[-1] == '\n' || end[-1] == '\r'))
192					*--end = '\0';
193				prout(linebuf);
194			}
195			/* A topic with no ****** terminator would otherwise
