/* Keep the end of the conversation when the terminal gets shorter.
 *
 * A window that loses rows loses them off the bottom, where the newest
 * text is: the line being typed, and the pause prompt waiting to be
 * answered. Scrolling first drops the oldest rows instead, which is the
 * part a player has already read. Without this, shrinking the terminal
 * during a pause took the prompt away and paged unread text with it.
 *
 * It has to happen before resize_term(), which is what does the
 * clipping -- by the time the windows are rebuilt the text is already
 * gone. So the new size is asked of the terminal directly rather than
 * of curses, which does not know it yet.
 *
 * How far to scroll is measured from the cursor, not from the height
 * lost. Until the conversation has filled the window its text sits at
 * the top with blank rows below, and scrolling by the whole difference
 * would throw away every line there was and leave the player looking at
 * an empty panel -- which is what the first attempt at this did.
 *
 * A terminal that will not say its size gets nothing done to it: the
 * old clipping behaviour is bad, and guessing would be worse. */
static void keep_tail(void) {
	struct winsize ws;
	int msgh, cury, curx;

	if (wmsg == NULL) return;
	if (ioctl(fileno(stdout), TIOCGWINSZ, &ws) != 0 || ws.ws_row <= 0)
		return;
	msgh = ws.ws_row - PANELH;
	if (msgh < 1) msgh = 1;
	getyx(wmsg, cury, curx);
	(void)curx;		/* getyx is a macro; it wants both */
	if (cury >= msgh)
		wscrl(wmsg, cury - (msgh - 1));
}

