42	
43		/* NO_COLOR is how a player asks for plain text without giving up
44		   the full-screen layout, which TERM=dumb would also cost them. */
45		use_colour = has_colors() && !(nc != NULL && *nc != '\0');
46		if (!use_colour) return;	/* the layout works without it */
47		start_color();
48		if (use_default_colors() == ERR)
