static void note_out(const char *s) {
	for (; *s != '\0'; s++) {
		if (*s == '\n')
			curlen = 0;
		else if (curlen < (int)sizeof curline - 1)
			curline[curlen++] = *s;
	}
	curline[curlen] = '\0';
}

