/* Set when the line above had to be written out again, so that
 * tui_readline knows whether the answer typed so far needs writing
 * after it. Echoing the answer when the prompt was never lost is what
 * put it on the screen twice. */
static int line_restored;

/* Put the unfinished line back on screen if the resize took it away.
 *
 * Whether it did is answered by looking for the line, not by guessing
 * from the size: every row is searched, because the cursor is not a
 * reliable pointer to it -- until the conversation has filled the
 * window curses leaves the cursor a row off, which read as "the prompt
 * is gone" and appended a second copy of every setup question.
 *
 * Found, and the cursor goes back to the end of it and nothing is
 * drawn. Missing, and it gets a row of its own: the window scrolls by
 * one first, because writing a newline would clear to the end of the
 * row the clip left the cursor on and take the tail of the line above
 * with it -- a sentence cut off mid-word. Losing the oldest row is what
 * this window does all the time; mangling the newest one is not. */
static void restore_curline(void) {
	char onscreen[sizeof curline];
	char *found;
	int r, maxy;

	line_restored = 0;
	if (curlen == 0) return;
	maxy = getmaxy(wmsg);
	for (r = maxy - 1; r >= 0; r--) {
		onscreen[0] = '\0';
		mvwinnstr(wmsg, r, 0, onscreen, (int)sizeof onscreen - 1);
		found = strstr(onscreen, curline);
		if (found != NULL) {
			wmove(wmsg, r, (int)(found - onscreen) + curlen);
			return;
		}
	}
	wscrl(wmsg, 1);
	wmove(wmsg, maxy - 1, 0);
	waddstr(wmsg, curline);
	line_restored = 1;
}

