1	#include "sst.h"
2	#include "tui.h"
3	#include <curses.h>
4	#include <term.h>
5	
6	/* Curses backend for the full-screen interface (sst -t).
7	 *
8	 * Layout: a quadrant panel (top left) and status panel (top right)
9	 * that repaint from the live game state before every prompt, and a
10	 * scrolling message window below them that carries the game's normal
11	 * conversation. All game output reaches this file through proutn()
12	 * and friends; panel text comes from the formatters in tuifmt.c.
13	 */
14	
15	#define PANELH (13)		/* border + header + 10 grid rows + border */
16	#define QUADW (29)		/* border + 25-char grid line + padding */
17	
18	int tui_active;		/* declared in tui.h; see the note there */
19	int tui_ingame;
20	
21	static WINDOW *wquad, *wstat, *wmsg;
22	static int use_colour;
23	
24	/* One pair per foreground; the background stays whatever the terminal
25	 * already uses, so the panels sit in the player's own colour scheme.
26	 *
27	 * Nothing is carried by colour alone. Every cell is a distinct glyph
28	 * and every coloured status value also spells its state out in words,
29	 * so a player who cannot tell red from green reads exactly what a
30	 * monochrome terminal shows. Keep it that way. */
31	#define CP_HOSTILE 1
32	#define CP_BASE    2
33	#define CP_STAR    3
34	#define CP_PLANET  4
35	#define CP_THING   5
36	#define CP_GOOD    6
37	#define CP_WARN    7
38	
39	static void start_colour(void) {
40		short bg = -1;
41		const char *nc = getenv("NO_COLOR");
42	
43		/* NO_COLOR is how a player asks for plain text without giving up
44		   the full-screen layout, which TERM=dumb would also cost them. */
45		use_colour = has_colors() && !(nc != NULL && *nc != '\0');
46		if (!use_colour) return;	/* the layout works without it */
47		start_color();
48		if (use_default_colors() == ERR)
49			bg = COLOR_BLACK;
50		init_pair(CP_HOSTILE, COLOR_RED, bg);
51		init_pair(CP_BASE, COLOR_CYAN, bg);
52		init_pair(CP_STAR, COLOR_BLUE, bg);
53		init_pair(CP_PLANET, COLOR_GREEN, bg);
54		init_pair(CP_THING, COLOR_MAGENTA, bg);
55		init_pair(CP_GOOD, COLOR_GREEN, bg);
56		init_pair(CP_WARN, COLOR_YELLOW, bg);
57	}
58	
59	static chtype attr_for_cell(char c) {
60		if (!use_colour) return A_NORMAL;
61		switch (cell_class(c)) {
62			case CELL_HOSTILE:	return COLOR_PAIR(CP_HOSTILE) | A_BOLD;
63			/* The ship takes no colour pair on purpose: bold alone keeps
64			   the terminal's own foreground, so it stands out on a light
65			   background as surely as on a dark one. A hardcoded white
66			   would be invisible on the former. */
67			case CELL_SHIP:		return A_BOLD;
68			case CELL_BASE:		return COLOR_PAIR(CP_BASE) | A_BOLD;
69			/* Stars are the most numerous thing on the grid and the least
70			   worth looking at, so they stay quiet -- and yellow is spoken
71			   for by the status panel, where it means caution. */
72			case CELL_STAR:		return COLOR_PAIR(CP_STAR);
73			case CELL_PLANET:	return COLOR_PAIR(CP_PLANET);
74			case CELL_WEB:		return COLOR_PAIR(CP_THING);
75			case CELL_THING:	return COLOR_PAIR(CP_THING) | A_BOLD;
76			case CELL_HIDDEN:	return A_DIM;
77			default:		return A_NORMAL;
78		}
79	}
80	
81	static chtype attr_for_status(int line) {
82		if (!use_colour) return A_NORMAL;
83		switch (status_class(line)) {
84			case STAT_GOOD:		return COLOR_PAIR(CP_GOOD);
85			case STAT_WARN:		return COLOR_PAIR(CP_WARN);
86			case STAT_BAD:		return COLOR_PAIR(CP_HOSTILE) | A_BOLD;
87			case STAT_DOCKED:	return COLOR_PAIR(CP_BASE) | A_BOLD;
88			default:		return A_NORMAL;
89		}
90	}
91	
92	/* How much of a panel line there is room for: the window less its two
93	 * borders, less the two-column indent the text is drawn at.
94	 *
95	 * Without it the panels do not clip, whatever make_windows() says they
96	 * do. waddch past the last column wraps to the next row of the same
97	 * window, so a line too long for a terminal shrunk below the 72x24
98	 * minimum landed on the row below -- over its left border and padding,
99	 * and for the last line over the bottom border, which is where
100	 * `xtsKlingons Left 2` and a bottom border reading `     7.00qj` came
101	 * from. At the minimum and above every line fits and nothing here
102	 * changes: the longest is Shields at 37 columns against the 40 the
103	 * status panel has at 72. */
104	static int panel_room(WINDOW *w) {
105		return getmaxx(w) - 3;
106	}
107	
108	/* Clipping a status line in silence is worse than the wrapping it
109	 * replaces, because what is left reads as a smaller, perfectly
110	 * plausible reading of the same field: `Torpedoes     1` for ten of
111	 * them, `Energy        367` for 3675.25, `Shields       DOWN, 10` for
112	 * 100%. Those are the fields a player checks in a fight, on a panel
113	 * that now looks intact and so gets believed. Garbage announced
114	 * itself; a truncated number does not.
115	 *
116	 * So the last column a clipped line has goes to a marker instead of to
117	 * one more digit. `Energy        36>` cannot be misread as a quantity,
118	 * and it says which lines to widen the terminal to see. */
119	static char clip_at(const char *s, int i, int room) {
120		return (i == room - 1 && s[i + 1] != '\0') ? '>' : s[i];
121	}
122	
123	/* Draw a grid line a cell at a time so each symbol carries its own
124	 * colour. Row labels and spacing classify as plain and stay uncoloured. */
125	static void draw_quad_line(int row, const char *s) {
126		int i, room = panel_room(wquad);
127	
128		wmove(wquad, row, 2);
129		for (i = 0; s[i] != '\0' && i < room; i++) {
130			char c = clip_at(s, i, room);
131			chtype a = attr_for_cell(c);
132			if (a != A_NORMAL) wattron(wquad, a);
133			waddch(wquad, (unsigned char)c);
134			if (a != A_NORMAL) wattroff(wquad, a);
135		}
136	}
137	
138	/* The label stays plain and the value takes the colour, so a glance
139	 * down the panel picks out the fields that are shouting. */
140	static void draw_status_line(int row, int line, const char *s) {
141		chtype a = attr_for_status(line);
142		int i, room = panel_room(wstat);
143	
144		wmove(wstat, row, 2);
145		for (i = 0; s[i] != '\0' && i < room; i++) {
146			if (i == STATLABEL && a != A_NORMAL) wattron(wstat, a);
147			waddch(wstat, (unsigned char)clip_at(s, i, room));
148		}
149		if (a != A_NORMAL) wattroff(wstat, a);
150	}
151	
152	/* The size the windows were last built for, so a read that comes back
153	 * empty can be told apart from one interrupted by the terminal
154	 * changing shape. */
155	static int builtlines, builtcols;
156	
157	/* Lay the three windows out for the terminal as it is now. Called
158	 * again after a resize, so it deletes what was there first.
159	 *
160	 * A terminal that has shrunk below the 72x24 the display asks for at
161	 * startup is not torn down mid-game: the panels keep their size and
162	 * the screen clips, which is ugly but leaves the player where they
163	 * were. Ending curses under them to say the window is too small would
164	 * be a worse answer to a mouse drag. */
165	static void make_windows(void) {
166		int msgh, statw, msgw;
167	
168		builtlines = LINES;
169		builtcols = COLS;
170		msgh = LINES-PANELH > 1 ? LINES-PANELH : 1;
171		statw = COLS-QUADW > 1 ? COLS-QUADW : 1;
172		msgw = COLS-2 > 1 ? COLS-2 : 1;
173		if (wmsg == NULL) {
174			wquad = newwin(PANELH, QUADW, 0, 0);
175			wstat = newwin(PANELH, statw, 0, QUADW);
176			wmsg = newwin(msgh, msgw, PANELH, 1);
177		} else {
178			/* Resized rather than remade, because the message window
179			   holds the conversation and a fresh one would be empty --
180			   including the prompt the player is being asked to answer
181			   at that very moment, which would leave the game looking
182			   hung. The panels are redrawn from the game state either
183			   way. */
184			wresize(wstat, PANELH, statw);
185			wresize(wmsg, msgh, msgw);
186		}
187		/* Set every time, not only on the first: keypad in particular is
188		   what turns a resize into KEY_RESIZE rather than into whatever
189		   bytes the terminal sent, and losing it would let the next drag
190		   answer a paging prompt. */
191		scrollok(wmsg, TRUE);
192		keypad(wmsg, TRUE);
193	}
